-- Sword duel record (run once in the Supabase SQL editor): who fought whom and who won.
create table if not exists public.duels (id bigint generated always as identity primary key, a text not null check (char_length(a) between 1 and 14), b text not null check (char_length(b) between 1 and 14), winner text not null, score text not null check (char_length(score) <= 7), created_at timestamptz not null default now());
alter table public.duels enable row level security;
create policy "read duels" on public.duels for select to anon using (true);
create or replace function public.record_duel(p_a text, p_b text, p_winner text, p_score text) returns void language plpgsql security definer set search_path = public as $$ begin if p_winner not in (p_a, p_b) or p_a = p_b then raise exception 'bad'; end if; if exists (select 1 from duels where a = p_a and b = p_b and created_at > now() - interval '20 seconds') then raise exception 'slow'; end if; insert into duels(a, b, winner, score) values (btrim(p_a), btrim(p_b), btrim(p_winner), p_score); end $$;
grant execute on function public.record_duel(text, text, text, text) to anon;
-- Developer: delete records (ids, or every match between two players, or everything); the server checks the code.
create or replace function public.admin_delete_duels(p_key text, p_ids bigint[], p_a text, p_b text) returns integer language plpgsql security definer set search_path = public as $$ declare n integer; begin if encode(sha256(convert_to('#ashen-admin' || upper(btrim(p_key)), 'UTF8')), 'hex') <> 'ae375075c3bc035551946756109fa2fcfda9798a59872242d1f7ddd14223fd00' then raise exception 'denied'; end if; if p_ids is not null then delete from duels where id = any(p_ids); elsif p_a is not null and p_b is not null then delete from duels where (a = p_a and b = p_b) or (a = p_b and b = p_a); else delete from duels where true; end if; get diagnostics n = row_count; return n; end $$;
grant execute on function public.admin_delete_duels(text, bigint[], text, text) to anon;
-- Player profiles: a public card per device; only the device holding the key can update its row.
create table if not exists public.profiles (pid text primary key check (char_length(pid) between 6 and 40), name text not null check (char_length(name) between 1 and 14), stats jsonb not null default '{}'::jsonb check (pg_column_size(stats) < 2048), key_hash text not null, updated_at timestamptz not null default now());
create index if not exists profiles_name_idx on public.profiles (name, updated_at desc);
alter table public.profiles enable row level security;
create policy "read profiles" on public.profiles for select to anon using (true);
revoke all on public.profiles from anon, authenticated;
grant select (pid, name, stats, updated_at) on public.profiles to anon;
create or replace function public.save_profile(p_pid text, p_key text, p_name text, p_stats jsonb) returns void language plpgsql security definer set search_path = public as $$ declare h text := encode(sha256(convert_to('#ashen-profile' || p_key, 'UTF8')), 'hex'); old text; begin if char_length(p_key) < 16 then raise exception 'bad key'; end if; select key_hash into old from profiles where pid = p_pid; if old is not null and old <> h then raise exception 'denied'; end if; if exists (select 1 from profiles where pid = p_pid and updated_at > now() - interval '5 seconds') then return; end if; insert into profiles(pid, name, stats, key_hash, updated_at) values (p_pid, btrim(p_name), p_stats, h, now()) on conflict (pid) do update set name = excluded.name, stats = excluded.stats, updated_at = now(); end $$;
grant execute on function public.save_profile(text, text, text, jsonb) to anon;
